from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # dp_free calculates the unconstrained branches and caches them.
        # It's defined here so that its cache perfectly persists across both
        # count_up_to(r) and count_up_to(l - 1) calls without cross-testcase MLE.
        @lru_cache(None)
        def dp_free(rem_len: int, cur_sum: int, prod_mod: int, started: bool, target_sum: int) -> int:
            if cur_sum > target_sum:
                return 0
            if rem_len == 0:
                return int(started and cur_sum == target_sum and prod_mod == 0)

            ans = 0
            for d in range(10):
                if not started and d == 0:
                    ans += dp_free(rem_len - 1, cur_sum, 1 % target_sum, False, target_sum)
                else:
                    if cur_sum + d <= target_sum:
                        ans += dp_free(rem_len - 1, cur_sum + d, (prod_mod * d) % target_sum, True, target_sum)
            return ans

        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            s = str(n)
            total = 0
            max_sum = 9 * len(s)

            for target_sum in range(1, max_sum + 1):
                # dp_tight handles the exact prefix constraint. 
                # Since it only visits O(len(s)) states and delegates to dp_free, it needs no cache.
                def dp_tight(pos: int, cur_sum: int, prod_mod: int, started: bool, tight: bool) -> int:
                    if cur_sum > target_sum:
                        return 0
                    if pos == len(s):
                        return int(started and cur_sum == target_sum and prod_mod == 0)
                    if not tight:
                        return dp_free(len(s) - pos, cur_sum, prod_mod, started, target_sum)

                    ans = 0
                    limit = int(s[pos])
                    for d in range(limit + 1):
                        next_tight = tight and (d == limit)
                        if not started and d == 0:
                            ans += dp_tight(pos + 1, cur_sum, 1 % target_sum, False, next_tight)
                        else:
                            if cur_sum + d <= target_sum:
                                ans += dp_tight(pos + 1, cur_sum + d, (prod_mod * d) % target_sum, True, next_tight)
                    return ans

                total += dp_tight(0, 0, 1 % target_sum, False, True)

            return total

        return count_up_to(r) - count_up_to(l - 1)
